parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "thought_process": {
      "type": "string",
      "description": "Brief explanation of why the geographic flags were set, specifically citing any mentions of 'EMEA', 'Hybrid', or specific country mandates."
    },
    "is_fully_remote": {
      "type": "string",
      "enum": ["Yes", "No"],
      "description": "Set to 'Yes' only if the job is explicitly 100% remote. Set to 'No' if it mentions hybrid, on-site, office-based, or is completely silent about remote work."
    },
    "relocation_mandatory": {
      "type": "string",
      "enum": ["Yes", "No"],
      "description": "Set to 'Yes' if the text requires moving to a specific city/country. Set to 'No' if relocation is not mentioned."
    },
    "country_bound_remote": {
      "type": "string",
      "enum": ["Yes", "No"],
      "description": "Set to 'Yes' if remote work is restricted to residents of one single country. Set to 'No' if it is global or region-wide (e.g., EMEA, Europe, LATAM)."
    }
  },
  "required": [
    "thought_process",
    "is_fully_remote",
    "relocation_mandatory",
    "country_bound_remote"
  ]
}

